import { TreemapAdapter } from '@dreadnought/react/unstyled';
const data = { id: 'all', label: 'Бюджет', children: [{ id: 'team', label: 'Команда', children: [{ id: 'web', label: 'Web', value: 60 }, { id: 'api', label: 'API', value: 40 }] }] };
export function Example() { return <TreemapAdapter label="Бюджет команды" data={data} />; }

import { TreemapAdapter, useTreemap } from '@dreadnought/react/unstyled';
const data = {id:'all',label:'Все',children:[{id:'a',label:'Проект A',value:60},{id:'b',label:'Проект B',value:40}]};
function Controls() { const {page} = useTreemap(); return <button disabled={page.page === page.count} onClick={() => page.change(page.page + 1)}>Следующая страница</button>; }
export function Example() { return <TreemapAdapter label="Распределение" data={data} pageSize={1}><Controls /><TreemapAdapter.Breadcrumb /><TreemapAdapter.Location /><TreemapAdapter.Plot tooltipContent={({defaultContent}) => <div>{defaultContent}</div>}>{({defaultContent}) => defaultContent}</TreemapAdapter.Plot><TreemapAdapter.Table /><TreemapAdapter.Pagination /><TreemapAdapter.Empty /></TreemapAdapter>; }
